"""Two-pose walk study: one fixed side body; two independently redrawn foot poses."""
from pathlib import Path
from PIL import Image
import numpy as np,cv2,cairosvg,io,base64,json
root=Path(__file__).resolve().parents[1];src=Image.open(root/'animation_lab/two_pose_walk/step_a.png').convert('RGBA');a=np.array(src);h,w=a.shape[:2];Y,X=np.indices((h,w))
white=(a[:,:,:3].min(axis=2)>245).astype('uint8');_,labels,_,_=cv2.connectedComponentsWithStats(white,8);a[:,:,3]=np.where(labels==labels[0,0],0,255)
boundary=np.interp(np.arange(w),[0,260,300,350,400,480,550,620,700,750,975],[800,905,918,934,945,951,947,938,918,897,800])[None,:];a[:,:,3]=np.where(Y>boundary,0,a[:,:,3]);body=Image.fromarray(a)
# Each pose is fully composed from an unchanged body and two complete outlined feet.
# Opposite tilts: each curved foot is drawn facing either forward or backward.
def foot(cx,direction):
 path='M -42 -73 C -42 -48 -48 -13 -52 8 C -55 27 -48 41 -26 47 C -4 54 29 54 50 50 C 71 46 74 33 63 20 C 57 13 46 10 37 7 C 31 4 29 -1 31 -9 L 40 -73 Z'
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}"><defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a6b996"/><stop offset="1" stop-color="#8c9d7b"/></linearGradient></defs><g transform="translate({cx},980) scale({direction},1) rotate({-13*direction})"><path d="{path}" fill="url(#g)" stroke="#713823" stroke-width="10" stroke-linejoin="round"/></g></svg>'''
 return Image.open(io.BytesIO(cairosvg.svg2png(bytestring=svg.encode()))).convert('RGBA')
frames=[]
for pose in (0,1):
 c=Image.new('RGBA',(w,h));c.alpha_composite(foot(350,-1 if pose==0 else 1));c.alpha_composite(foot(610,1 if pose==0 else -1));c.alpha_composite(body)
 # Place the foot under the hand visually in front by removing only the short body
 # contour crossing its attachment, retaining outer foot edges and all other outlines.
 pixels=np.array(c); line=(X>305)&(X<405)&(Y>895)&(Y<955)&(pixels[:,:,0]<150)&(pixels[:,:,1]<105)&(pixels[:,:,2]<85)
 mask=(line.astype('uint8')*255);mask=cv2.dilate(mask,np.ones((3,3),np.uint8));pixels[:,:,:3]=cv2.inpaint(pixels[:,:,:3],mask,5,cv2.INPAINT_TELEA);c=Image.fromarray(pixels)
 c.thumbnail((300,330),Image.Resampling.LANCZOS);buf=io.BytesIO();c.save(buf,'PNG',optimize=True);frames.append('data:image/png;base64,'+base64.b64encode(buf.getvalue()).decode());c.save(root/f'animation_lab/two_pose_walk/pose_{pose}.png')
html='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سبارك تمشي بصورتين</title><style>*{box-sizing:border-box}body{margin:0;min-height:100svh;display:grid;place-items:center;padding:20px;background:#fbf6ef;color:#382b26;font-family:system-ui,sans-serif}.card{width:min(100%,650px);background:#fff;border:1px solid #f0e3d6;border-radius:28px;padding:26px;text-align:center;box-shadow:0 12px 35px #8a563315}.badge{display:inline-block;border-radius:99px;background:#fff0e3;color:#b3582d;padding:7px 14px;font-size:13px;font-weight:bold}h1{font-size:24px}p{line-height:1.8;color:#756158}.stage{position:relative;height:300px;overflow:hidden;background:#fffaf5;border-radius:20px}.floor{position:absolute;bottom:30px;left:5%;right:5%;height:2px;background:#e9d8c8}img{position:absolute;bottom:25px;left:0;width:180px;height:198px;object-fit:contain}button{border:0;border-radius:99px;background:#bd603a;color:#fff;font:700 16px system-ui;padding:13px 25px;cursor:pointer;margin-top:18px}button:focus-visible{outline:3px solid #916541;outline-offset:3px}.note{font-size:13px}</style><main class="card"><span class="badge">معاينة منفصلة • مش داخل التطبيق</span><h1>سبارك تمشي بصورتين 🐾</h1><p>صورتين للخطوات يتبادلوا بسرعة وهي تمشي لليمين.</p><div class="stage" id="stage"><div class="floor"></div><img id="pet" alt="سبارك بالجنب تمشي لليمين بصورتين متبادلتين"></div><button id="replay">شغّلي المشية من جديد ↻</button><p class="note">تجربة بصورتين فقط للمراجعة 💛</p></main><script>const frames=FRAMES;const img=document.getElementById('pet'),stage=document.getElementById('stage');let token=0;function run(){const id=++token,start=performance.now(),duration=5000;img.src=frames[0];function tick(now){if(id!==token)return;const elapsed=now-start,t=Math.min(elapsed/duration,1);img.src=frames[Math.floor(elapsed/300)%2];img.style.transform=`translateX(${Math.max(0,stage.clientWidth-180)*t}px)`;if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}document.getElementById('replay').onclick=run;if(matchMedia('(prefers-reduced-motion: reduce)').matches)img.src=frames[0];else run();</script></html>'''.replace('FRAMES',json.dumps(frames));(root/'web_extra/spark-two-pose-walk.html').write_text(html,encoding='utf8')
